    if sep_row is not None:
        region = grid[sep_row + 1:]
    else:
        sep_col = next(c for c in range(w)
                       if len({grid[r][c] for r in range(h)}) == 1)
        region = [row[sep_col + 1:] for row in grid]

    counts = {}
    for row in region:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    return [[0 if value == background else 2 for value in row]
